export const LESSONS = {"threepiles":{"topicId":"mt_Eqk6oSbySH","title":"三份故事，合成一整份","formal":"三个加数的情境与条形模型","summary":"每段表示故事里的一部分，合成整体时不能遗漏或重复。可以先选凑成十的两个部分；另外一个部分仍要加进来。算式里的每个数都要能在故事中找到对应。","reflection":"如果把汽车、自行车和公交车合在一起，答案应该说多少辆什么？","batch":"B12"},"storytwo":{"topicId":"mt_yTWxkzzoOZ","title":"问的地方变了，怎么算","formal":"两步加减、未知量与比较问题","summary":"先看问的是结果、最开始的数量，还是中途变化的数量。同一句“拿走”，可能需要用加法倒着找原来的数量。比较多少时，差与两边的数量也不能混在一起。","reflection":"同样是花掉12又找到5，问现在有多少与问最初有多少，计划哪里不同？","batch":"B12"},"plansteps":{"topicId":"mt_CDa5AVakLE","title":"先想两步，再动手","formal":"两步加减问题的计划与方法选择","summary":"可以先完成一个变化，也可以先合并同类变化；每个已知量都要在计划里发挥正确作用。每步保留中间量，最后回答原问题。方法是否顺手，要结合这些数和自己的理由来看。","reflection":"先加两次要送出的数量，再从原来的一堆拿走，为什么也能算出剩余？","batch":"B12"},"equalgroups":{"topicId":"mt_PZ909yPrEC","title":"每一份，都一样多","formal":"乘法与等组连加","summary":"3份，每份2个，可以记成2+2+2，也可以记成3×2。份数和每份多少是两个不同的量；几份大小不同时，不能直接把它们当成同样的几份。","reflection":"3份每份2个，与3个再加2个，哪里不一样？","batch":"B13"},"sharegroups":{"topicId":"mt_LpSuPgL31x","title":"分给几人，还是每袋几个","formal":"等分与包含除","summary":"12个分给3人，问每人几个；12个每3个装一袋，问几袋。都能用12÷3，但答案中的4说的是不同的事。平均分要求每份相同。","reflection":"同样是12÷3，什么时候4表示每份多少，什么时候表示有几份？","batch":"B13"},"screenshare":{"topicId":"mt_1GDEHyEZYH","title":"把这一堆分公平","formal":"屏幕上的等分与成组","summary":"拖动或点选搬动每一颗，原来的数量不增加也不消失。每个人都拿到一些，还不一定是平均分；要检查各份是不是一样多。","reflection":"屏幕上的三份怎样对应桌上的三只玩具？","batch":"B13"},"bagstories":{"topicId":"mt_wh3UqnWsa7","title":"袋子里的故事","formal":"乘除情境的结构","summary":"知道几袋和每袋多少，可以合起来找全部；知道全部，再按人数分或按每袋大小装，会问出不同的问题。先看数量之间的关系。","reflection":"15颗分给3人，与每袋3颗，谁是已经知道的？","batch":"B13"},"groupsproblems":{"topicId":"mt_qUjW0N1cYO","title":"贴纸、苹果和小桌子","formal":"等组与平均分问题","summary":"盘子、袋子和桌椅只是情境。先找全部、份数和每份多少，再让图与问题对应。图上每一份都要一样多。","reflection":"4张桌子每桌4把椅子，可以怎样摆，才能看出一共16把？","batch":"B13"},"divisionmeaning":{"topicId":"mt_iNdrM2-oJf","title":"同一道除法，两种分法","formal":"除法的两种含义","summary":"56÷8既可以问分给8人每人多少，也可以问每8个装一袋有几袋。不能交换总数和分的对象。剩下一些时，要说明它们没有凑成完整的一份。","reflection":"得到7时，它数的是人手里的物品，还是装好的袋子？","batch":"B13"},"arraystart":{"topicId":"mt_GRWwTDZ3wD","title":"排成整齐的队伍","formal":"乘除法的阵列模型","summary":"3行，每行4个，整齐排成12个。按行看与按列看，总数相同；知道一共有12个、每行4个，也能倒着找到3行。","reflection":"行和列换一个方向，为什么没有添东西却能换一种乘法？","batch":"B13"},"rowsums":{"topicId":"mt_B1zj1RwQ3a","title":"每一行，写成一份","formal":"阵列与等加数连加","summary":"每一行贡献同样的数量。3行4个可以写成4+4+4=12；行长不一样时，这个等组写法就不合适。","reflection":"怎样从4+4+4看出要摆几行、每行几个？","batch":"B13"},"mulsymbols":{"topicId":"mt_zOWwLxa77y","title":"给摆法写个短名字","formal":"乘号、除号与等号","summary":"×记录等组，÷记录怎样分，=表示两边一样多。12=3×4也成立，等号不要求答案只能写在右边。","reflection":"3×4与3+4摆出来会一样吗？","batch":"B13"},"turnarray":{"topicId":"mt_C9ZfT-4cgn","title":"转一下，数量会变吗","formal":"乘法交换律与除法边界","summary":"阵列转向后，同一批物品从3行5个变成5行3个，数量不变。除法交换总数和份数会变成另一个问题：12÷3和3÷12不同。","reflection":"为什么乘法能换位置，除法却不能直接照搬？","batch":"B13"},"productmeaning":{"topicId":"mt_gtTl3R5buH","title":"几份，每份几个","formal":"乘法的数量含义","summary":"4×6可以对应4份、每份6个。两种因子顺序的积相同，但故事中份数与每份多少仍各有角色。重复加法是等组的入口，不是所有乘法情境的全部含义。","reflection":"同样24个，4袋每袋6个与6袋每袋4个，故事哪里变了？","batch":"B13"},"evenhalves":{"topicId":"mt_0u4KLbvBa1","title":"分成两边，会剩一个吗","formal":"奇偶、等分与个位规律","summary":"偶数能两两配好，也能分成相同的两份。每个十本身能配好，所以十进制整数的奇偶由个位决定；0没有剩余，也是偶数。","reflection":"23为什么要看最后的3，而不是前面的2？","batch":"B13"},"tables2510":{"topicId":"mt_HhuSDxwDNM","title":"从两份、五份、十份开始","formal":"2、5、10的乘除事实","summary":"两倍可以看成两个相同部分；同一个数的五倍是十倍的一半。一组乘法还连着对应的除法。几次回忆只是练习，不代表已经流利。","reflection":"忘了5×6时，怎样借10×6找回来？","batch":"B13"},"tables348":{"topicId":"mt_wQ89AEXhz3","title":"加倍，再加倍","formal":"3、4、8的乘除事实","summary":"4份可以由2份加倍，8份再由4份加倍。乘法事实和对应除法一起用，忘记时可以回到图中重建。","reflection":"4×7已经知道，怎样接出8×7？","batch":"B13"},"tables12":{"topicId":"mt_K5jM7vlVhA","title":"把熟悉的事实连起来","formal":"12以内乘除事实与推导","summary":"换顺序能找到伙伴，拆开能借熟悉的事实。想不起来时，可以回到图里，借已经会的那一份找回来。","reflection":"7×8卡住时，你想借哪一个已经会的事实？","batch":"B13"},"missingfactor":{"topicId":"mt_GDG9_SZmsO","title":"这一边藏起来了","formal":"除法作为未知因子","summary":"32÷8可以问8乘几等于32。把缺少的一边补回阵列，再乘回去检查；除法和乘法围绕同一份整体。","reflection":"知道8×4=32，能接出哪两道除法？","batch":"B13"},"unknownproducts":{"topicId":"mt_xZvDCYA5Ae","title":"空格换位置，办法也换吗","formal":"乘除等式中不同位置的未知量","summary":"空格可能是每份、份数或全部。□÷5=9要找的是全部，7×□=63要找的是其中一边；求出后放回原等式检查。","reflection":"怎样知道这次应该找全部，还是找其中一边？","batch":"B13"},"factorpairs":{"topicId":"mt_nZkL5-XjRX","title":"同一堆，能排几种长方形","formal":"因数对与交换","summary":"每个长方形的两边是一对相乘得到总数的整数。3×8和8×3是同一对，不能重复计数；1×24也不能漏掉。","reflection":"从1开始试，怎样说明所有不同的长方形都找到了？","batch":"B13"},"mentalproducts":{"topicId":"mt_pjfmCMMPjO","title":"先找一对顺手的伙伴","formal":"心算中的单位与乘法结合","summary":"三数相乘可以先挑顺手的一对；每个原数仍要用一次。乘1保持原量，乘0得到0。用十作单位时，结果也要带着十的单位。","reflection":"2×7×5先合哪一对顺手？其他顺序为什么也对？","batch":"B13"},"tensproducts":{"topicId":"mt_isojCL9yy-","title":"一颗换成一捆十","formal":"乘整十数与位值","summary":"7×30是7份3个十，一共21个十，也就是210。依据是单位变成十，不是对所有数都能“后面添0”；小数更不能照搬这个口诀。","reflection":"7×3和7×30的图可以同样摆，为什么数量不同？","batch":"B13"},"productways":{"topicId":"mt_Lb2ZnMdkYR","title":"转一转，切一刀，换个搭档","formal":"乘法的交换、分配与结合","summary":"阵列旋转、把每行拆成两段、先合三数中的一对，都能改变算法而保留数量。8×7拆成8×5与8×2，两边都要乘8。","reflection":"8×5+2为什么没有装下8×7里全部的点？","batch":"B13"},"derivepatterns":{"topicId":"mt_aivrWs6jrS","title":"发现规律，再试着说明","formal":"重复推理与概括","summary":"半份的分子是分母的一半；单位扩大十倍，同样摆法代表的积也扩大十倍。例子帮助检验猜想，为什么一直成立还需要理由。","reflection":"看见几个例子相同，和说明为什么一定这样，有什么区别？","batch":"B13"},"mixedfacts":{"topicId":"mt_WX30dzi4dt","title":"忘了也能找回来","formal":"乘除事实与灵活推导","summary":"可以把一大份切成两个熟悉的部分，再合起来；乘除事实也能相互检查。","reflection":"9×7能借10×7减去哪一整份？也能怎样分成两块？","batch":"B13"},"tablepatterns":{"topicId":"mt_w6MxaaoMXZ","title":"表里的规律，从哪里来","formal":"乘法表规律与结构解释","summary":"5的倍数个位在5和0之间交替；两个偶数相加仍能配成两份；交换行列让乘法表有对称伙伴。图可以支持解释，几个例子本身不是一般证明。","reflection":"两个偶数各分成两份，再接在一起，为什么还能分成两份？","batch":"B13"},"largerfacts":{"topicId":"mt_8A3pZNOp7Z","title":"借小算式，算大数量","formal":"位值与分配的心算策略","summary":"40×60可以看成4个十乘6个十，也就是24个百。7×15拆成7×10与7×5，两部分都要乘7。","reflection":"360÷9与36÷9，哪一份变大了十倍？","batch":"B14"},"writtenstart":{"topicId":"mt_DyGBW3ZHh3","title":"把大块拆开算","formal":"分拆与书面乘除","summary":"23×4分成20×4与3×4，算完再合起来。竖着记只是把这些数量放进各自的位置。","reflection":"竖式里十位的2，为什么不能只算2×4？","batch":"B14"},"shortproduct":{"topicId":"mt_18fK9sQdIz","title":"十个换一捆，再往前走","formal":"短乘法与进位","summary":"先乘当前这一位，再加上一位送来的整捆。十个合成一个更大的单位，剩下的留在原位。","reflection":"47×6里从个位送出的4，到了十位表示多少？","batch":"B14"},"longproduct":{"topicId":"mt_q9EaJc2FP8","title":"第二行为什么要挪一格","formal":"长乘法与面积分拆","summary":"34×27的两行分别是34×7与34×20。第二行乘的是20，放对位置才能合成原来的数量。","reflection":"面积图里的四块，怎样合成竖式的两行？","batch":"B14"},"bigproduct":{"topicId":"mt_XLP1IM3Qbb","title":"更多数字，同样的单位","formal":"多位数长乘法","summary":"数字更多，仍是每位相乘、合十进位，再把不同单位的部分相加。先估一个大概，可以发现数量差得太远的错误。","reflection":"第二行漏掉一个0，为什么结果会差这么多？","batch":"B14"},"shifttens":{"topicId":"mt_LlMl2PbaZe","title":"数字搬家，值会变","formal":"乘除10、100、1000","summary":"小数点标着个位边界。每个数字向左移一格，表示的量扩大十倍；向右移一格，就变成原来的十分之一。","reflection":"3.45×100为什么不是3.4500？","batch":"B14"},"shiftfine":{"topicId":"mt_wPgpMJ0-PA","title":"再小一点的位置","formal":"更精细小数的位值变化","summary":"45.2除以1000得到0.0452，最后的2来到万分位。空位置里的0不能漏，小数点也不用跟着数字走。","reflection":"同一个2，搬到不同位置后代表的量有什么不同？","batch":"B14"},"shortdivide":{"topicId":"mt_MCu_SNg_OW","title":"这一位剩下的，带到下一位","formal":"短除法与余数","summary":"一份十没有分完，可以换成十份一，再和原来的一起分。每一位都要记，分不到也要留0。","reflection":"125÷8剩5，什么时候保留5，什么时候需要多一个袋子？","batch":"B14"},"divide16":{"topicId":"mt_FvEq4heNBx","title":"一份里有十几个，也能分","formal":"两位数除法与方法选择","summary":"先估这一段能分几份，再乘回去、看剩余。记得紧凑还是把乘减展开，可以按自己熟悉的程度选择。","reflection":"两种记法都成立时，哪一种让你更容易检查？","batch":"B14"},"longdivide":{"topicId":"mt_WsM4EmdOLe","title":"每一步都能倒着检查","formal":"长除法与余数表达","summary":"先分、乘回去、拿走，再把下一位带下来。4752÷13是365余7；把剩下7再平均分13份，就是每份7/13。","reflection":"为什么剩下的7要除以13，不能直接写成小数点后的7？","batch":"B14"},"remainders":{"topicId":"mt_p-nbe0w_lf","title":"剩下的人，也要坐上车","formal":"情境中的余数与两步问题","summary":"52人坐每辆9人的车，5辆还剩7人，要6辆。若问52颗能装满几个9颗袋子，只能装满5袋。","reflection":"同一个52÷9，为什么两个故事的答案不同？","batch":"B14"},"roundanswers":{"topicId":"mt_QU5R7Aajy9","title":"答案留到多细才够用","formal":"答案精度与情境取舍","summary":"量长度、分金额和准备整辆车，需要的答案不同。尽量保留中间结果，最后再按用途取近似值。","reflection":"5.33辆车为什么不能按普通四舍五入只准备5辆？","batch":"B14"},"factorlab":{"topicId":"mt_FHIAv6dfhU","title":"哪些伙伴，两个数都有","formal":"因数、倍数与共有部分","summary":"能整除它的是因数；一份份接着增加得到倍数。两个数都拥有的才叫共同，1不能漏，倍数也没有最大一个。","reflection":"24与36共同拥有的因数，和共同的倍数有什么区别？","batch":"B14"},"factoruse":{"topicId":"mt_0Wg5F97osg","title":"拆出一个顺手的搭档","formal":"整除、平方与因数策略","summary":"24×25可以先把24拆成6×4，再让4与25合成100。判断6的倍数，需要同时满足2和3的整除条件。","reflection":"24×4×25为什么多算了？","batch":"B14"},"parityrules":{"topicId":"mt_oxfxzbat3k","title":"两颗落单的，可以作伴","formal":"奇偶运算的结构","summary":"每个奇数都能配成若干对，再剩1颗。两个奇数合起来，两个落单的恰好又成一对。偶数份的同样数量也能两份一组。","reflection":"不算347+129的总数，怎样知道会不会有落单的？","batch":"B14"},"primetest":{"topicId":"mt_y1XCVsIelg","title":"只能排成长长一行吗","formal":"质数与合数","summary":"大于1、只有1和自身两个不同因数的数叫质数。1只有一个因数；2是偶数，也是质数。51还能排成3×17，所以不是质数。","reflection":"为什么不能用“奇数就是质数”来判断？","batch":"B14"},"squarecube":{"topicId":"mt_gxCIASSezX","title":"铺成方，搭成立方","formal":"平方数与立方数","summary":"7²是7×7，4³是4×4×4。小小的2和3说的是有几个相同因子相乘，不是乘以2或3。","reflection":"4³为什么不是4×3？","batch":"B14"},"factorcode":{"topicId":"mt_bZC-wqWX7Y","title":"让办法替你逐个找","formal":"因数算法与表格规则","summary":"把起点、检查、记录条件和下一步说清楚，就能让同一个办法逐个检查。表格里的下一格也可以引用上一格，照同一条规则继续。","reflection":"从1找因数时，怎样保证24本身也不会漏掉？","batch":"B14"},"primeforest":{"topicId":"mt_xhoOWnhtHq","title":"拆法不同，最后的积木相同","formal":"质因数分解、最大公因数与最小公倍数","summary":"把大于1的整数拆到每块都是质数，换条拆法，质数和各自的份数仍相同。共有的份数组成最大公因数，够两边使用的份数组成最小公倍数。","reflection":"24与36都有2和3，为什么不能把所有重复的都算进最大公因数？","batch":"B14"},"structurebridge":{"topicId":"mt_hImiKNiaNh","title":"换个样子，还是同一个关系","formal":"跨表示的数学结构","summary":"长方形保留平行四边形的对边与角关系。3份(n+5)拆开是3n+15。八分之一、0.125与12.5%是在同一个整体上说同一个量。","reflection":"换了图、字母或数的写法，哪些关系仍然不变？","batch":"B15"},"bracketlab":{"topicId":"mt_8jFSnXxqQD","title":"把这一组先抱在一起","formal":"括号与分组","summary":"括号告诉大家先把里面算成一块。小括号、中括号与大括号在这里都用来分组，里面还有一层时从最里面开始。","reflection":"只移动括号，为什么会改变结果？","batch":"B15"},"orderlab":{"topicId":"mt_jHgRQ4hR0g","title":"大家怎样读出同一个结果","formal":"运算顺序","summary":"约定好顺序，大家才能把同一行算式读成同一个意思。先括号，再幂，再同层乘除从左到右，最后同层加减从左到右。","reflection":"12÷2×3为什么不能先把2×3算成6？","batch":"B15"},"expressions":{"topicId":"mt_4WaKWECpcv","title":"把故事装进一行算式","formal":"数值表达式的书写与解释","summary":"“8与7合起来，再取2份”写作2×(8+7)。括号保存先后关系。比较一个量与它的3倍，有时不用先把大数算出来。","reflection":"4×(365−12)里，哪一块先成为一个整体？","batch":"B15"},"powerorder":{"topicId":"mt_X5cypSGoGU","title":"小小的符号，改了哪一步","formal":"含幂与根的运算顺序、倒数","summary":"−3²表示把3平方后取负，(−3)²把负3整体平方。根号也管住它下面的一整块。非零数乘它的倒数得到1；0没有倒数。","reflection":"为什么−3²与(−3)²会有不同结果？","batch":"B15"},"signedproducts":{"topicId":"mt_rxInpOQ74w","title":"方向翻过去，结果怎样走","formal":"有理数乘除的符号规则","summary":"连续改变一份的方向，结果也要延续原来的规律。同号相乘为正，异号相乘为负；除法可以乘回去检查。这个规则不能直接搬到两个负数相加。","reflection":"−3×−2与−3+−2，为什么不能用同一句口诀？","batch":"B15"},"undocalc":{"topicId":"mt_VUQNveSYjQ","title":"走回去，要先撤回哪一步","formal":"逆运算及其适用范围","summary":"先乘3再加2，走回去就先减2再除3。平方与非负平方根在非负数上相互撤回；从负数先平方再开平方，会留下它的绝对值。","reflection":"算术能倒查回来，就一定选对故事中的运算了吗？","batch":"B15"},"decimalproduct":{"topicId":"mt_SoDP1fSQEB","title":"小单位算完，再换回来","formal":"小数乘整数与位值","summary":"4.56是456个百分之一，取7份得到3192个百分之一，也就是31.92。3.2×5得到16.0，与16表示同一个量。","reflection":"3192为什么在这道题里不是三千多？","batch":"B15"},"decimaldivide":{"topicId":"mt_lU-2aTRB9f","title":"没分完的，还能换得更小","formal":"小数除以整数","summary":"一份一可换成十份十分之一，剩下的也照样换。13写成13.00没有改变数量，只是让剩余能继续分到更小的单位。","reflection":"13÷4剩1，怎样继续分，而不是把1直接接在商后面？","batch":"B15"},"calculatormeaning":{"topicId":"mt_NmvuwVUFRS","title":"机器算出数，故事决定怎么用","formal":"计算器、估计与情境解释","summary":"先估个大概，再核对输入。250÷8=31.25：安排全部人需要32辆车，装满盒子只31盒，绳子平均分则每份31.25厘米。","reflection":"计算器显示的31.25，为什么不是三个故事的共同答案？","batch":"B15"},"estimatecheck":{"topicId":"mt_ilPrU0cbtT","title":"先看大概，发现差得太远","formal":"估算检验与适当精度","summary":"487×23可看成500×20，大约一万。估计能抓住少一位或错小数点的错误，但接近不保证精确正确；估计与精确各有用途。","reflection":"500变大而20变小，能只凭一个方向判断估计一定偏大吗？","batch":"B15"},"mentalchoices":{"topicId":"mt_vmW2cb5c7A","title":"给数字找顺手的搭档","formal":"灵活的心算策略","summary":"45×8可以分成40×8与5×8，也可以连续加倍。6.5×4把6与0.5都算进去。99×6借100×6后，还要退回多算的一份6。","reflection":"同一道题可以有几种正确办法，哪种让你更容易记住中间的量？","batch":"B15"},"decimalestimate":{"topicId":"mt_3m0pA-aeat","title":"小数点走错，会差多远","formal":"小数计算的估算检验","summary":"4.87×30大约是5×30=150；63.6÷20约等于60÷20=3，所以31.8差得太远。估计帮助查错，不代替精确计算。","reflection":"2.46×400估成2.5×400，为什么能帮助检查984？","batch":"B15"},"scaleandpair":{"topicId":"mt_EmR5n58jZt","title":"复制几份，还是搭配几种","formal":"倍数缩放、对应与未知因子","summary":"3倍是三份相同的量。4件上衣各配3条裤子，要把每一种搭配都留下，得到12种。已知放大后的量，也能倒着找到原来的一份。","reflection":"“3倍”与“多3”，分别改变了哪一部分？","batch":"B15"},"groupstories":{"topicId":"mt_Zdv-b-iW5K","title":"这道故事，到底在找哪一个量","formal":"乘除问题的结构与单位","summary":"6袋每袋8颗在找全部；28厘米剪成每段4厘米在找段数；28颗分4人在找每人几颗。同样28÷4，答案中的7可以表示不同的东西。","reflection":"看到“每”字就用除法，为什么会算错6袋每袋8颗的总数？","batch":"B15"},"combineproducts":{"topicId":"mt_AR-K72OIIO","title":"拆块、复制和搭配","formal":"分配律、倍数与组合问题","summary":"14×6拆成10×6与4×6，两部分都要算。塔高是15米的3倍，与高出3米不同。3种面包配4种馅料，要找全12种搭配。","reflection":"多添一种馅料，会增加一份还是三份搭配？","batch":"B15"},"timesmeaning":{"topicId":"mt_U4cIBXVug4","title":"几倍，是几份同样多","formal":"乘法比较的意义","summary":"一条作参照，另一条由几份相同参照量接成。“4倍”是四份原量，“多4”只添4。比较必须说清谁是谁的几倍。","reflection":"用同样的4和4，四倍与多四分别得到多少？","batch":"B15"},"timesproblems":{"topicId":"mt_6-j1NO2ZUH","title":"藏起来的，可能是哪一份","formal":"乘法比较中的不同未知量","summary":"已知一份7、要3份，求全部；已知全部36、是4份，求一份；已知24与6，求相当于几份。先认清藏起来的量，再选乘或除。","reflection":"36是4倍时，为什么原来的一份不是36×4？","batch":"B15"},"storyoperations":{"topicId":"mt_RXnyhCRYXA","title":"把一个问题，接成几步","formal":"多步问题的运算选择与检查","summary":"先想这一步在找什么，再把两个量接起来。算术正确还不够：同样得到4的2+2与2×2，描述的事情可能不同。逆算只检查数字，不能替故事选关系。","reflection":"哪一步选错了运算，即使计算准确，也会走到另一件事上？","batch":"B15"},"halfpaper":{"topicId":"mt_-hTTat0mBR","title":"怎样分，双方才一样多","formal":"二分之一与相等的份","summary":"把同一个整体平均分成两份，每份是二分之一。只切成两块还不够，两块必须一样大；一堆8颗平均分两组，每组4颗。","reflection":"两块都有了，为什么还不一定各是一半？","batch":"B16"},"quarterpaper":{"topicId":"mt_g3W0mdADVu","title":"再分一次，一份变多大","formal":"四分之一","summary":"对折以后再对折，可以得到四个相等的部分。每个是四分之一，四份合回整个。12颗平均分四组，每组3颗。","reflection":"把12颗每4颗装一袋，与分成4组，哪里不一样？","batch":"B16"},"shapeparts":{"topicId":"mt_xACS3rWWDp","title":"一整个，能怎样拼回来","formal":"图形的二等分与四等分","summary":"圆可以分成两个半圆，长方形可以分成四个等份。两个二分之一、四个四分之一都拼成一个整体。数份数，不数切线。","reflection":"同一个长方形换个方向分，还能得到四个相等的份吗？","batch":"B16"},"smallershare":{"topicId":"mt_hyvHv2BCwb","title":"来分的人多了，每份呢","formal":"单位分数的大小与整体","summary":"同样大的整体，平均分的份数越多，每份越小。四分之一比二分之一小；比较时必须固定整体大小。","reflection":"大披萨的四分之一，一定比小披萨的二分之一小吗？","batch":"B16"},"areaparts":{"topicId":"mt_idbKDrf9qZ","title":"样子不同，也能一样多","formal":"等面积分割与单位分数","summary":"等份要求面积相等，不要求每份长得完全相同。一个整体分成6个等面积部分，每个是1/6；四个等面积部分也可以有不同形状。","reflection":"怎样用小格检查两块形状不同的部分是否一样多？","batch":"B16"},"setfractions":{"topicId":"mt_MyGblah2yY","title":"换个名字，拿到的没有变","formal":"分数的数量意义与等值","summary":"1/2的10是5。相同整体上，两份四分之一正好覆盖一份二分之一；2/4和1/2是同一个量的不同名字。","reflection":"为什么一个整体换了大小，同样的1/2也可能拿到不同数量？","batch":"B16"},"unitsets":{"topicId":"mt_k2WE0-22-4","title":"先分组，再取你要的几组","formal":"集合的单位与非单位分数","summary":"12颗分4组，一组3颗，三组9颗。写选中部分的分数时，整体包括选中和没选中的全部物品。","reflection":"选中3颗、没选中9颗，整体到底是9颗还是12颗？","batch":"B16"},"nonunitamount":{"topicId":"mt_3y7xKP9MjU","title":"一份知道了，几份就接起来","formal":"求一个量的几分之几","summary":"求20的3/5，先20÷5得到一份4，再取3份得到12。分母决定分几份，分子决定取几份。","reflection":"只算出24÷8，为什么还没有回答24的3/8？","batch":"B16"},"lineplaces":{"topicId":"mt_Kr3IyA6m-O","title":"让一份在路上有个位置","formal":"分数作为数轴上的数","summary":"0到1的距离是一个单位。分四段后，1/4、1/2、3/4各占一个确定的位置；四段只有三个内部刻度。分数是一个数。","reflection":"3/4为什么不在3与4之间？","batch":"B16"},"unitcopies":{"topicId":"mt_09sySPqM9Z","title":"一小步接一小步，可以越过1","formal":"单位分数的累加与假分数","summary":"5/8是五个1/8相加。走四个1/3会超过1，到4/3；七个1/4到7/4。增加的是小份个数，份的大小不变。","reflection":"1/4加1/4，为什么不能把下面的4也相加？","batch":"B16"},"wholefractions":{"topicId":"mt_AYzE1EAvI0","title":"分数也能刚好是整数","formal":"整数与分数的统一表示","summary":"5个整体可以写成5/1。4/4与1落在同一点，6/3与8/4都是2，5/2则是2又1/2。分数可以等于或大于1。","reflection":"分母是1，表示把每个整体怎样分？","batch":"B16"},"mixedpoints":{"topicId":"mt_PsylzZ9lHW","title":"各种名字，共用一条线","formal":"混合数系的位值与顺序","summary":"整数、小数与分数都表示数，负数也在同一条线上。数字的实际大小由它所在的位决定；十倍关系可以继续向大、向小延伸。","reflection":"写法更长的数，一定更大吗？","batch":"B16"},"orderforms":{"topicId":"mt_uDJY0X0hgo","title":"名字不同，也能排在一起","formal":"混合表示的比较与不等号","summary":"0.75与3/4在同一点；负数越靠左越小。<与>不含相等，≤与≥允许相等，≠表示不相等。","reflection":"−0.8与−3/4，哪个更靠左？为什么？","batch":"B16"},"manycopies":{"topicId":"mt_HJA2Oz-Zh1","title":"每人一小份，合起来要多少","formal":"分数乘整数与情境解释","summary":"5人各吃3/8，共吃15/8，也就是1又7/8个披萨；按整个买至少2个。4段各2/3米共8/3米。乘的是份数，单位份不变。","reflection":"“吃了多少”和“至少买几个”，为什么不是同一个答案？","batch":"B16"},"sharewholes":{"topicId":"mt_4Km38F4L-6","title":"几个完整的，也可以分给更多人","formal":"分数与除法","summary":"3个整体平均分4人，每人拿到3个1/4，所以3÷4=3/4。50平均分9份，每份5又5/9；乘回9应回到50。","reflection":"不够每人一个完整的，为什么并不代表不能分？","batch":"B16"},"modelrecipe":{"topicId":"mt_K3R0yaHVcx","title":"把厨房与铺地装进图里","formal":"乘法、分数与单位的建模","summary":"行列表示铺了多少格；500克的3/4是375克。1米与100厘米是同样长的量，换单位要保留长度，结果要带单位。","reflection":"同一根绳从米换成厘米，变的是长度还是记录它的数字？","batch":"B16"},"translateamount":{"topicId":"mt_3VmBdlAeOZ","title":"一件事，用几种图来讲","formal":"图形、算式与数轴的互译","summary":"分享可以同时画成几份和写成除法；4×23可以拆成4×20与4×3，在条形、面积和按位计算中分别是80与12。0.3与3/10在同一点。","reflection":"换了一张图，怎样认出原来的80和12还在？","batch":"B16"},"viewlinks":{"topicId":"mt_CUmjcE7W6c","title":"图换了，数量关系还在","formal":"缩放、百分数与图表的互译","summary":"三份相同量用条形和乘法都能表达。35个百分之一是35/100、0.35、35%。读两次图上的量，求差要写成减法。","reflection":"35%为什么不是35个整体？","batch":"B16"},"precisefractions":{"topicId":"mt_HY8Yycu_rz","title":"写给别人看，要说清哪一种量","formal":"单位、分数术语与数学记号","summary":"35厘米与35米不同。分子数取了几份，分母说明一个整体分几份；等值分数表示同一个量。3.5元与3.50元数值相等，统一金额格式时常保留两位小数。","reflection":"只有一个35，别人能知道你量的是什么吗？","batch":"B16"},"fractionreason":{"topicId":"mt_2ESZh70NyS","title":"让别人看见，你为什么这样想","formal":"共同单位、错误分析与推理链","summary":"3/4与2/3换成共同的十二分之一，分别是9份与8份。乘几十的那一行要放在十位；三角形的三个角可搬到一点拼成平角。有限图例是理解与说明的起点，不等于一般证明。","reflection":"找出错误答案，与指出哪一步破坏了关系，差在哪里？","batch":"B16"},"representationmap":{"topicId":"mt_9KmVWCuh5_","title":"一个关系，穿过几种图","formal":"代数、坐标与比例表示","summary":"4份相同未知量再加27等于87，可画条形也可写4n+27=87。坐标的两项有各自的含义；圆图、分数与百分数可以表示同一个比例。","reflection":"把横轴和纵轴交换，还在讲同一件事吗？","batch":"B16"},"storyfraction":{"topicId":"mt_dXq9VWm31W","title":"让每个数，都找得到它说的东西","formal":"数量关系的图式与方程","summary":"每个数都要连着故事中的量。长320厘米用去125厘米，可以写320−125=195；分数条表示整个与部分；数轴上的位置要沿同一个单位读。","reflection":"数轴画到4，为什么3/4仍然在0与1之间？","batch":"B16"},"unitorder":{"topicId":"mt_IfEgu0X449","title":"份数变了，大小怎样排","formal":"单位分数与同分母分数比较","summary":"同一个整体，分得越细，一份越小；同样大小的小份，拿得越多，总量越大。这是两个不同的问题，不能只盯某一个数字。","reflection":"1/5比1/2小，为什么4/5又比2/5大？","batch":"B17"},"fractionchoices":{"topicId":"mt_SsLWS_APM7","title":"先想要找什么，再动手","formal":"分数问题的策略选择","summary":"先看故事里的整体、部分和要找的量，再选分、取、比较或相加减。结果要能回到原来的情境，不能看到“总共”就一律相加。","reflection":"先找一份与直接相加，各在什么故事里合适？","batch":"B17"},"samepartcompare":{"topicId":"mt_HnKbuCliNS","title":"拿同样几份，为什么不一样多","formal":"同分子、同分母与相同整体","summary":"3/8与3/4都取三份，但每份不同；5/6与2/6每份相同，但取的份数不同。用图比大小时，整体必须一样大。","reflection":"把一张图画成两倍长，会不会改变分数这个数本身？","batch":"B17"},"fractionbench":{"topicId":"mt_SXbZ3bC9z7","title":"找一个共同的参照","formal":"通分比较与基准数","summary":"把3/8与5/12都分成二十四分之一，可以比较9份和10份；5/8与3/7分处一半两边，借一半就能判断。","reflection":"什么时候借一半就够，什么时候需要继续细分？","batch":"B17"},"beyondoneorder":{"topicId":"mt_PL9VkDwXfh","title":"离整个多远，跨过整个多远","formal":"近整数与假分数的比较","summary":"都在1下面时，离1越近的越大；跨过1也沿同一单位数轴。7/5=21/15，4/3=20/15。","reflection":"离1差得少的更大，这个办法能直接套在1两边吗？","batch":"B17"},"recutnames":{"topicId":"mt_FP-mjXaq3B","title":"切细一点，还是原来的量","formal":"等值分数的生成与约分","summary":"每一份都再分两份，上下的份数同时翻倍，涂出的量不变。反过来成组并回，也能保留同一个量。","reflection":"上下各加1，为什么通常不能替代再分或合并？","batch":"B17"},"samenames":{"topicId":"mt_ebPelt-qAl","title":"给同一个量留下几个名字","formal":"分数等值的乘除原则","summary":"2/3、4/6、6/9在同一位置。乘相同因子是在重分每一份；乘n/n相当于乘1。自由说明仍要靠自己的理由。","reflection":"同样乘一个数，为什么量没变；只改一边又会怎样？","batch":"B17"},"simplestparts":{"topicId":"mt_b7T-CjOYUR","title":"能不能合到更简单","formal":"公因数、最简分数与共同分母","summary":"18/24可以一起除以6到3/4，也可以先除2再除3。9/12与原量相等，只是还没到最简。比较两种份要用共同的倍数。","reflection":"约分找共同因数，通分找共同倍数，各自在改变什么？","batch":"B17"},"percentpatterns":{"topicId":"mt_jCy07DyBNU","title":"从几个例子，搭一条可用的规则","formal":"等价运算、数列规则与百分数","summary":"×25可以写成×100再÷4。每次多4、从5开始的数列，第n项是4n+1。35%能由三个10%和一个5%拼成；换整体，各块金额跟着改变。","reflection":"知道下一项，还不够直接知道第100项，差在哪里？","batch":"B17"},"tenpieces":{"topicId":"mt_YzM5goBctT","title":"十个小份，合回多少","formal":"十分之一与分数除法","summary":"一个整体分十等份，十个十分之一合回1。3个整体分给10人，每人拿到3个十分之一，所以3÷10=3/10。","reflection":"数到十份时，为什么量是1而不是10？","batch":"B17"},"decimalorder2":{"topicId":"mt_IegHBHERVa","title":"小数也沿着同一条线排","formal":"两位小数的位值比较","summary":"先比较大的单位，遇到第一个不同位置就能决定。3.72与3.27个位相同，十分位先决定；末尾0不改变数量。","reflection":"比较大小和竖着相加，为什么看的先后不一样？","batch":"B17"},"tenthtohundred":{"topicId":"mt_NaqEP8xDhZ","title":"一长条，换成十小格","formal":"十分之一转百分之一","summary":"一个十分之一包含十个百分之一。3/10先换成30/100，再加4/100得到34/100；相加的是同样小的份。","reflection":"3/10+4/100为什么不能把上下的数字都相加？","batch":"B17"},"decimalnames":{"topicId":"mt_Vi4Vo5xs_g","title":"点后面的0，守着哪个位置","formal":"十分位、百分位与分数互译","summary":"0.62是62个百分之一，0.07是7个百分之一，0.7则是7个十分之一。0不是装饰，它让数字留在正确的单位位置。","reflection":"0.07与0.7只差一个0，为什么量差十倍？","batch":"B17"},"decimalmeasure3":{"topicId":"mt_sA2OvTiech","title":"小到千分之一，也能拼和取","formal":"三位小数的计算与应用","summary":"相同单位站在同一列，十个小单位换一个大单位。1.5=1.500；1.500−0.375=1.125。两段也可自选，只要相接恰好到1。","reflection":"把0.4记成0.400，变的是量还是写法？","batch":"B17"},"thousandparts":{"topicId":"mt_kdWoAel3Zl","title":"再放大一点，里面还有位置","formal":"千分之一与十进细分","summary":"一个百分之一再分十份就是千分之一。一个十分之一有100个千分之一。0.345在0.34与0.35中间；放大显示不改变原来的单位。","reflection":"画面被放大十倍，为什么数没有跟着变大？","batch":"B17"},"raggeddecimals":{"topicId":"mt_933BohS9BH","title":"写得更长，不一定更大","formal":"不同位数小数的比较","summary":"0.45比0.405大，但0.4又比0.87小。数量由位置决定，不能套“长的一定大”或“短的一定大”。0.7=0.70=0.700。","reflection":"两个相反的长度口诀，怎样各找一个反例？","batch":"B17"},"fractionmeasure":{"topicId":"mt_wB-GBDkoNr","title":"把分数带回钱与长度","formal":"分数、小数与计量单位","summary":"3.20元的1/4是0.80元，也就是80分。2.5米剪掉0.75米还剩1.75米。1千克的3/10是300克，也可以记0.3千克。","reflection":"同一段长度从米换成厘米后，为什么数字变了？","batch":"B17"},"fdpswitch":{"topicId":"mt_4K1dr204Hi","title":"一个量，三种写法一起看","formal":"分数、小数与百分数转换","summary":"分数线也表示除法：3/8=3÷8=0.375。1/5=0.2=20%。1/3是循环小数0.333…，不能截成0.3再说相等。","reflection":"30%、1/3、0.35，哪些需要精确值，哪些可以借参照比较？","batch":"B17"},"decimalstops":{"topicId":"mt_SBkTGjiZjZ","title":"除到什么时候，会停下来","formal":"有限小数与循环小数","summary":"先把分数化到最简。分母的质因子只有2和5时，可以换成10的幂作分母，所以小数会结束；还有别的质因子时会循环。有限操作样例不等于已经证明一般规律。","reflection":"6/15与4/15下面都写15，为什么一个会停，一个会循环？","batch":"B17"},"structurechoices":{"topicId":"mt_hlGKg5M7qJ","title":"换个结构，事情变好算","formal":"因数重组、等值表示与角关系","summary":"25×16可以拆成25×4×4，先得到100。75%与3/4一样多，求80的3/4可以先÷4再×3。直线上相邻的角合为180°，能用来推出未知角。","reflection":"25×16顺手的办法，为什么不能把23×16也凑成100？","batch":"B17"},"mixedrename":{"topicId":"mt_o_p-3tCxiM","title":"整份和零头，来回换名字","formal":"带分数与假分数互化","summary":"11个1/4里有两组完整的4/4，剩3/4，所以11/4=2又3/4。3又2/5是15个1/5再加2个，共17/5。","reflection":"从整份换成小份，为什么小份的大小不能变？","batch":"B17"},"fractionfour":{"topicId":"mt_gNUE4B3vuk","title":"同样两个数，四种不同动作","formal":"数系综合运算与方法辨别","summary":"加减连接同样小的份，乘法缩放，除法比较能放下几组。分数乘法即使先通分，也要把两个分母相乘；有效但多一步的方法不算错。负数方向、混合数和小数都保留原量。","reflection":"为什么同一对分数，换一个运算符就需要重新想动作？","batch":"B17"},"joinfractions":{"topicId":"mt_a1FdAsRKOF","title":"同样的小份，可以接起来","formal":"同分母分数加减","summary":"2/5与2/5共有4个五分之一；6/8拿走3/8还剩3/8。加减的是份数，小份的大小没有改变。","reflection":"为什么2/5加2/5不是4/10？","batch":"B18"},"fractioncarry":{"topicId":"mt_CBHwluE6Lp","title":"接过一个整个以后","formal":"同分母加减与超过1的和","summary":"3/5+4/5是7个五分之一，其中5个合成1，余下2个，所以是1又2/5。超过1以后，小份的单位仍然不变。","reflection":"十个八分之一，为什么不是十个整体？","batch":"B18"},"mixedexchange":{"topicId":"mt_70qDTI14td","title":"整份可以换开，小份可以合拢","formal":"带分数加减与退位","summary":"小份不够减，可以把一个整份换成同样大小的小份。4又2/6变成3又8/6，量没有变。也可以先全部换成假分数再算。","reflection":"把整份换开后，为什么不能让整份的个数留在原处？","batch":"B18"},"relatedparts":{"topicId":"mt_-V7EnqU7gG","title":"把一大份切成同样小的份","formal":"分母有倍数关系的分数加减","summary":"1/3切成2个1/6，再接1/6就是3/6，也就是1/2。两种份先变成同一单位，才能合在一起数。","reflection":"1/3换成六分之一时，上面的1为什么也要变？","batch":"B18"},"fractionstories":{"topicId":"mt_ZLqYE7la4Z","title":"接绳子、倒果汁，用同一种份","formal":"分数加减的情境建模","summary":"先看是在合起来还是拿走，再把情境中的量画成同单位的份。图中的长度、容量或数量不能混作同一单位。","reflection":"同样出现两个分数，为什么不一定都做加法？","batch":"B18"},"splitfraction":{"topicId":"mt_VgOePicFYK","title":"这段量，还能分成哪几组","formal":"分数的加法分解","summary":"3/8可以分成三个1/8，也可以分成1/8与2/8。拆成哪几组可以变，总量不变；1+1+1/8仍是2又1/8。","reflection":"只是交换两组的先后，算不算一种新的拆法？","batch":"B18"},"unlikeparts":{"topicId":"mt_14T5yPXUq_","title":"两种份都切细，再来算","formal":"异分母分数加减","summary":"2/3与5/4都切成十二分之一，得到8/12+15/12=23/12。共同单位不一定只有一种，但每个原量都必须保持不变。","reflection":"分成24份也能算，为什么不能只把下面的数改成24？","batch":"B18"},"repeatfraction":{"topicId":"mt_TgHxujL81r","title":"每次这么多，连续拿几次","formal":"分数与整数相乘","summary":"4次3/8就是把3/8连续接4次，得到12/8=1又1/2。2又1/3拿3次，整份和零头都要一起参与，得到7。","reflection":"每次拿3/8与每次拿1/8，走4次会有什么不同？","batch":"B18"},"fractionarea":{"topicId":"mt_gx6KQK5-Kx","title":"横着取一部分，竖着再取一部分","formal":"分数边长与面积","summary":"把单位正方形横分3份、竖分4份，每小格面积是1/12。选2列、3行重合6小格，面积是6/12=1/2。小格可以是等面积长方形。","reflection":"边长1/3与1/4围成的小格，为什么面积不是1/7？","batch":"B18"},"productfractions":{"topicId":"mt_AabJisinfi","title":"一部分里面，再取一部分","formal":"分数乘分数","summary":"2/3的4/5在面积图中重合8小格，每小格是1/15，得到8/15。两个正的真分数相乘，结果比它们各自都小；乘大于1的数则不同。","reflection":"“相乘一定变大”在哪种情况下不成立？","batch":"B18"},"fractionrecipe":{"topicId":"mt_lvaSGHwvQ5","title":"做半份、做一份半，材料跟着变","formal":"分数乘法情境与估计","summary":"一份配方用2又1/3杯，做1又1/2份需要3又1/2杯。先估大概，再用图把整份和零头全部表示出来，回看结果是否合理。","reflection":"做一份半与加半杯，为什么不是同一个动作？","batch":"B18"},"portionoperator":{"topicId":"mt_J339bO7qLe","title":"取几成，先认清这次的整个","formal":"分数与百分数作为乘法算子","summary":"取200的3/4可以先分4份再取3份。20%=0.2，取60的20%得到12。连续变化时，下一步的整个可能已变，折扣量和折后量要分清。","reflection":"先减20%再加10%，后一个10%是以哪个量为整个？","batch":"B18"},"dividebyten":{"topicId":"mt_kDMKJ5Ztt6","title":"每个数字都往小的单位走","formal":"整数除以10、100与小数位值","summary":"37÷10=3.7，3在个位，7在十分位。4÷100=0.04，4在百分位。小数点固定，数字每右移一位，其值变为原来的十分之一。","reflection":"37除以10，为什么不能只删掉最后的7？","batch":"B18"},"countsmallgroups":{"topicId":"mt_1PAWhRhpdg","title":"大段里面，装得下几小份","formal":"整数除以单位分数","summary":"4里面有20个1/5，所以4÷(1/5)=20。20×1/5又回到4。这里在数小组，不是在把4平均分给五个人。","reflection":"每组越小，同样的总量能装的组数会怎样？","batch":"B18"},"sharesmallpart":{"topicId":"mt_ifPDOYvUqm","title":"已经很小的一份，再平均分","formal":"单位分数除以整数","summary":"把1/3再平均分给4人，每人是原整个的1/12。四个人的1/12合回1/3。结果的分母仍以最初的整个为参照。","reflection":"每人拿到这小份的1/4，为什么又说是整个的1/12？","batch":"B18"},"fractiondividewords":{"topicId":"mt_rCMdwG-YOE","title":"分给几个人，还是装成几杯","formal":"分数除法的两种情境","summary":"半千克分给3人，每人1/6千克；2杯按每份1/3杯分装，可以装6份。前者已知人数求每份，后者已知每份求份数。","reflection":"“每份多少”与“能分几份”分别在问哪一个量？","batch":"B18"},"fractionsanity":{"topicId":"mt_e7filQgayF","title":"先看大概，发现不可能的答案","formal":"分数加法估计与合理性检查","summary":"2/5加1/3是11/15，介于1/2与1之间。2/5加1/2一定超过1/2，而3/7小于1/2，所以3/7不可能是它们的和。估计能排除错误，精确结果仍需计算。","reflection":"估计落在合理范围，能保证最后一个数字完全正确吗？","batch":"B18"},"fractionquotient":{"topicId":"mt_9Y96vxG_LH","title":"把每组变成1，组数会变吗","formal":"分数除法与倒数","summary":"2/3里面能装5/6组4/5。两边一起乘5/4，每组变成1，总量变成5/6，组数没变。这说明除以4/5等于乘它的倒数5/4。","reflection":"为什么两边要一起改变，只把第一个分数倒过来不行？","batch":"B18"},"categoryuse":{"topicId":"mt_1VSfm9yiLn","title":"多出来的是哪一段","formal":"分类数据的频数、总数与差","summary":"每类有多少、合起来多少、相差多少，是三种不同的问题。逐个配对后留下的部分是差；每人只答一次时，总次数才等于人数。","reflection":"最多的那一类有8个，为什么“多几个”不一定是8？","batch":"B19"},"playgroundstudy":{"topicId":"mt_kxeuXm6EyC","title":"操场上，什么最受欢迎","formal":"引导式统计调查","summary":"先说明在什么时间观察什么，再逐条记、整理、画图。连续几天的使用次数，可以包含同一个人多次出现；不能直接当成不同人数。","reflection":"三天共记录12次，能说有12个不同的人吗？","batch":"B19"},"digitalstudy":{"topicId":"mt_yrvYKSwSRZ","title":"让表格帮忙数","formal":"数字工具收集与整理数据","summary":"本地表单把问题和回答对应起来。COUNTIF按条件数出记录，统计范围必须包含所有行。图和结论来自同一份表。","reflection":"表格少算最后一行，图再漂亮也可靠么？","batch":"B19"},"ownstudy":{"topicId":"mt_Y6JmLjnfRP","title":"一份小调查，从头做到尾","formal":"统计调查的设计、收集与呈现","summary":"给每个人问同样的三个问题，记录各人的回答，再选一个问题整理。15人各答3题仍是15人。两条发现应带数据，并说明范围。","reflection":"有45个填写的格子，为什么不能说调查了45个人？","batch":"B19"},"studyplan":{"topicId":"mt_SHVyE1CLUa","title":"先想清楚，怎样才知道","formal":"统计调查计划与表示选择","summary":"先明确对象、时间和记录方法。柱图适合比较次数，点图保留分布，表适合查准确数。结论需要回到原问题，并说明一处限制。","reflection":"同一份数据，什么时候用图，什么时候直接看表？","batch":"B19"},"checkrecords":{"topicId":"mt_QHT16CrFO-","title":"这条记录靠得住吗","formal":"数据验证、名义与有序分类","summary":"先保留原记录。有凭据才能更正，没有凭据就标记未知或暂不计入，不能编一个数补空白。颜色名称没有固有高低；评分有顺序，但相邻差距不一定相等。","reflection":"两个回答一样，是两个人一样想，还是同一个人记了两次？怎样知道？","batch":"B19"},"betterquestion":{"topicId":"mt_O-U263ukg1","title":"把一个模糊问题问清楚","formal":"改进统计调查问题与过程","summary":"把“大家爱运动吗”变成对特定一组人、特定一周的可记录问题。留下谁、怎样、何时，按记录总结，再指出下一次能改进的地方。","reflection":"只问一起踢球的朋友，能代表所有孩子吗？","batch":"B19"},"measurestory":{"topicId":"mt_6gpryAnpoZ","title":"数字背后，发生了什么","formal":"观测数、测量背景与报告精度","summary":"频数相加得到观察次数。测量要交代对象、工具、方法、单位和精度。整点附近堆积可能来自取整，单看堆积不能断言原因。","reflection":"很多人写21:00，能证明他们都在同一分钟睡着吗？","batch":"B19"},"digitalcharts":{"topicId":"mt_X53txVXOcG","title":"一条记录，变成一个图案","formal":"数字计数工具与图画统计图","summary":"逐条观察再记，图例说明每个图案代表多少。图、计数和表格应来自同一批记录；屏幕杯子只是模拟。","reflection":"一个图案表示2票，3个图案为什么不是3票？","batch":"B20"},"chartfamilies":{"topicId":"mt_eKJG-0eC6D","title":"换张图，换个问题","formal":"分组频数表、饼图与比较图","summary":"连续数值按不重叠区间整理；份额要以总数作整体；比较两组数据要同时引用两边的量。","reflection":"每个角度加起来是360度，是否就一定画对了？","batch":"B20"},"timeorcategory":{"topicId":"mt_ChjMU2GDJa","title":"这些点，该连起来吗","formal":"分类柱图与时间折线图","summary":"时间轴的位置按实际间隔排；连线帮助描述随时间变化。不同水果的类别没有连续中间值，不能把连线当作趋势。","reflection":"9点、10点、12点之间的两段空隙应该一样宽吗？","batch":"B20"},"displaychoices":{"topicId":"mt_TiFjjvBMaY","title":"哪张图更容易看清","formal":"比较数据表示与分布","summary":"同一数据可以换表示。图例、共同尺度和想回答的问题决定读法。比较两组身高时，要看整组的分布和范围。","reflection":"图画大一点，数量就一定更多吗？","batch":"B20"},"linequestions":{"topicId":"mt_H6LlpWgEYS","title":"最高的时候，涨得最快吗","formal":"折线图读数与变化问题","summary":"点的高度是当时的量，前后之差是变化；还要看经过多久。月总雨量可以相加，但不能从连线读出某一天的雨量。","reflection":"温度最高的一天，为什么不一定升温最多？","batch":"B20"},"timetable":{"topicId":"mt_Cqm8iy48UI","title":"赶上哪一班，路上多久","formal":"时刻表、双向表与经过时间","summary":"先对准行与列，再读取交点。时间按60分钟进一小时；10:50到11:20是30分钟，不能把钟面写法当小数减。","reflection":"时刻11:20与1.2小时是同一件事吗？","batch":"B20"},"timebuilder":{"topicId":"mt_HlNSurPVDp","title":"把变化沿时间画出来","formal":"折线图构造、插值与变化率","summary":"选均匀刻度，按实际时间间隔落点并连接。中间值是连接假设下的估计；每小时变化要用变化量除以经过时间。","reflection":"跨两小时涨4度，和一小时涨4度一样快吗？","batch":"B20"},"fractiondots":{"topicId":"mt_IHipFGTFEY","title":"小数轴上，也能堆起记录","formal":"分数测量数据点图与均分","summary":"每个点是一条测量，横轴的每个八分之一位置都保留。总量要把所有点表示的量加起来，平均分要再除以份数。","reflection":"一列点有3个，表示长度3，还是同一个长度出现3次？","batch":"B20"},"piepieces":{"topicId":"mt_bESTSBB0wK","title":"把所有份额拼成一圈","formal":"饼图的份额、角度与数量","summary":"整圈是总数，整周360度。每类的角度等于该类占总数的比例乘360度。同样大的扇区，在不同总数里不一定代表相同人数。","reflection":"两张图都有四分之一块，能直接说人数一样吗？","batch":"B20"},"boxsummary":{"topicId":"mt_8VjmxR1yfw","title":"五个位置，藏了多少细节","formal":"最小最大须线箱线图","summary":"最小、下四分位、中位数、上四分位和最大概括一组数据。本活动须线到最小与最大；箱宽是中间一半的跨度。五个数相同，分布细节仍可能不同。","reflection":"右边的须更长，表示那里人更多，还是数值更分散？","batch":"B20"},"dotrecords":{"topicId":"mt_JRzXQl9M7c","title":"一个点，到底代表什么","formal":"数值点图与频数","summary":"横位置是每人的记录值，竖着叠的是出现次数。所有整数刻度都保留，没有点的7仍然有位置；全部点数才是观察人数。","reflection":"5上面堆6个点，是一个人读6本，还是六个人各读5本？","batch":"B20"},"histogram":{"topicId":"mt_oderfUBZPw","title":"把一串数装进相邻格子","formal":"等宽直方图与分组信息","summary":"按连续、等宽、不重叠的区间归组，150属于150≤h<160。相邻区间柱子相接；分组会藏掉确切原值。","reflection":"只看150到160这一柱，能知道有几个人正好145吗？","batch":"B20"},"scattercraft":{"topicId":"mt_BdAeZJUOir","title":"每一对数，放一个点","formal":"散点图构造与目测拟合","summary":"每点保留同一对象的一对数。趋势线是一条概括点云的直线，不是按编号逐点连，也不必穿过原点。范围内的预测仍是估计。","reflection":"点有时在线上有时在线下，能否有不止一条合理趋势线？","batch":"B20"},"scattermeaning":{"topicId":"mt_8atyuvPUZc","title":"一起变化，就是谁造成谁吗","formal":"散点相关、趋势与因果边界","summary":"向上和向下的趋势都可以是联系；没有明显直线趋势也不等于一切关系都不存在。点贴线的程度不同于线有多陡；第三个因素可能同时影响两边。","reflection":"天气变热时冰淇淋和游泳人数都增加，能说冰淇淋让人去游泳吗？","batch":"B20"}};
